{
  "vulnerable_symbols": [
    "axios",
    "axios.request"
  ],
  "trigger": "在 axios 1.7.0–1.19.x 中配置 adapter:'fetch' 且 Object.prototype 已被污染（如 headers）时，fetchOptions 继承字段会覆盖已构造 Request 的请求头。",
  "exploit_evidence": [],
  "fixed_version": "1.20.0",
  "summary_zh": "Axios fetch适配器误传原始fetchOptions，原型污染时可篡改请求头，升级1.20.0。"
}
